//! This module holds any data structures used in the texture section of the file.
//! The texture section is used for multiple things:
//! - *colorpalette:* Every picoCAD 2 has a colorpalette that can be customized.
//! For that the project file stores an array with 16 RGB colors which is the actual palette and 2 other arrays with 16 indices which represent the index off the color to be used as a shade.
//! - *texture-file:* This section also stores the texture file.
//! - *special colors:* This section also determines the background color and the color to be used as a transparent color.

use serde::{Deserialize, Serialize};

#[derive(Debug, Deserialize, Serialize, Clone, PartialEq)]
pub struct Texture {
    /// Colorpalatte index to use as the background color.
    background_color: usize,
    /// Colorpalatte index to use as the transparent color.
    transparent_color: usize,
    /// Represents the 16 colors of the palette.
    /// Each item in the outer vector of length 16 is another vector with exactly 3 items which represent the red, green and blue values of each color.
    colors: Vec<Vec<f64>>,
    /// Represents the lighter shadows.
    /// Each item is an index on the colorpalette.
    /// This means that if the first element in `shade_pal_1` is `2`, the third color in the color palatte will be used as the light shadow for the first color.
    shade_pal_1: Vec<usize>,
    /// Represents the dark shadows.
    shade_pal_2: Vec<usize>,
    /// Represents the pixels inside the texture file.
    /// This string is exactly 16384 characters long where each character represents a hexadecimal index for the colorpalette.
    /// The texture file is 128 by 128 pixels and is stored as rows, meaning the first 128 characters of this String represent the first line from left to right.
    /// Then it starts again in the second like on the left and so on.
    pixels: String,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_serde() {
        let foo: Texture = serde_json::from_str(EXAMPLE).unwrap();
        let s = serde_json::to_string(&foo).unwrap();

        assert_eq!(foo, serde_json::from_str(&s).unwrap());
    }

    const EXAMPLE: &str = r#"
    {
      "background_color":6,
      "shade_pal_1":[0,0,1,1,2,3,3,2,6,7,4,5,6,10,10,12],
      "shade_pal_2":[0,0,0,0,1,1,1,1,3,2,2,3,3,4,4,6],
      "pixels":"",
      "colors":[[0,0,0],[0.11372549019608,0.16862745098039,0.32549019607843],[0.49411764705882,0.14509803921569,0.32549019607843],[0.37254901960784,0.34117647058824,0.30980392156863],[0.67058823529412,0.32156862745098,0.21176470588235],[0,0.52941176470588,0.31764705882353],[0.51372549019608,0.46274509803922,0.61176470588235],[1,0,0.30196078431373],[0.16078431372549,0.67843137254902,1],[1,0.46666666666667,0.65882352941176],[1,0.63921568627451,0],[0,0.89411764705882,0.21176470588235],[0.76078431372549,0.76470588235294,0.78039215686275],[1,0.8,0.66666666666667],[1,0.92549019607843,0.15294117647059],[1,0.94509803921569,0.90980392156863]],
      "transparent_color":0
    }
"#;
}
